-- Per version: v, date, items = { { s = "add"|"chg"|"fix", fr = { title, text }, en = { title, text } } }
local _, ns = ...
ns.WHATSNEW = {
  { v = "1.0.0-beta.169", date = "2026-11-19", items = {
    { s = "chg", fr = { "Meilleur équipement, le BiS de Naowh en tête", "Si la BiS List de Naowh est installée, la première pièce de chaque emplacement des onglets Pré-BiS 60 et BiS 60 est celle de Naowh, marquée « BiS Naowh (simulé) ». C'est ton propre choix si tu as rempli « My BiS » chez Naowh, sinon son classement simulé (MythicSim). Le classement calculé de WL Helper Gear passe dessous, comme autre choix. Rien n'est copié : la liste est lue en direct dans l'addon de Naowh." }, en = { "Best gear", "With Naowh's BiS List installed, its simulated BiS comes first in each slot, ours under it." } },
    { s = "chg", fr = { "Onglet PvP 60", "Chaque pièce dit ce qu'elle coûte. Pour le set d'honneur, c'est l'honneur et les marques (« 9 000 honneur + 15 marques Vallée d'Alterac »). Pour les pièces de rang, c'est le rang PvP requis (« Rang PvP 13 (Warlord) requis »). L'intro précise que le gain est calculé avec des poids PvE et ne compte pas l'endurance." }, en = { "PvP tab", "Honor and marks, or the PvP rank needed, for each piece." } },
    { s = "chg", fr = { "Champs de bataille, bonus du jour bien visible", "En haut de la fenêtre, une bannière sur toute la largeur donne le nom du champ de bataille en bonus en grand et en doré, avec une étoile, une ligne qui explique, et « Y aller » vers son maître de guerre. Sans bonus, une ligne discrète. La pastille reste sur la carte." }, en = { "Battlegrounds", "Today's bonus is now a full-width banner with the battleground's name, a short line and a \"Go there\" button." } },
    { s = "chg", fr = { "Fenêtre large", "Le tableau passe en colonnes (pièce, gain, provenance) au lieu d'une longue ligne étirée." }, en = { "Wide window", "The table uses columns." } },
    { s = "fix", fr = { "Onglet PvP 60", "Plus de pièces de rang de l'autre faction (Field Marshal, Knight-Captain... pour un Horde, et inversement)." }, en = { "PvP tab", "No rank pieces of the other faction." } },
  } },
  { v = "1.0.0-beta.168", date = "2026-11-19", items = {
    { s = "chg", fr = { "Champs de bataille, fenêtre refaite pour être lisible", "" }, en = { "", "" } },
    { s = "chg", fr = { "", "Elle s'ouvre depuis l'accueil et le hub (ligne « Champs de bataille », dans Guilde et groupes), en plus de /wlh pvp." }, en = { "", "" } },
    { s = "chg", fr = { "", "Deux onglets : « Champs de bataille » et « Set PvP »." }, en = { "", "" } },
    { s = "chg", fr = { "", "Chaque carte de champ de bataille montre le nom (avec une pastille « Bonus aujourd'hui » quand il l'est), ton rang en couleur avec sa barre et x / y, puis un seul chiffre fort : les victoires qu'il reste, avec les défaites et la source en petit. Le maître de guerre tient sur une ligne, avec « Y aller » à droite. Les niveaux et les autres villes sont dans l'infobulle." }, en = { "", "" } },
    { s = "chg", fr = { "", "Le bonus de la semaine tient en une ligne. Un clic ouvre le calendrier du jeu." }, en = { "", "" } },
    { s = "chg", fr = { "", "Le set PvP est un vrai tableau : emplacement, pièce dans sa couleur de qualité, honneur, marques et gain, avec l'infobulle de l'objet (Maj-clic pour le lien). En tête : ton honneur sur ce qu'il faut, tes marques par champ de bataille avec une barre, et le champ de bataille à faire d'abord. La quête Field of Honor est dans une carte repliable, avec ses 3 semaines et un bouton « Y aller »." }, en = { "Battlegrounds window redone for reading", "Home and Hub entry, two tabs, one strong number per battleground card, the PvP set as a table, Field of Honor folded." } },
  } },
  { v = "1.0.0-beta.167", date = "2026-11-19", items = {
    { s = "chg", fr = { "Meilleur équipement, refait en tableau", "Une ligne par emplacement, groupée en Armure, Bijoux et Armes, avec deux lignes pour les anneaux et les bijoux. Chaque ligne donne ton BiS, le gain par rapport à ce que tu portes, sa provenance (boss · donjon, métier, quête, marchand) et le niveau requis en rouge s'il est au-dessus du tien. « N choix › » déplie les remplaçants. L'infobulle est celle de l'objet, et Maj-clic met son lien dans la discussion." }, en = { "", "" } },
    { s = "chg", fr = { "", "En haut : combien de BiS tu portes (« 1/16 portés »), une barre par emplacement, et les filtres Tout / À obtenir / Dans les sacs." }, en = { "", "" } },
    { s = "chg", fr = { "À faire ensuite", "Les 3 endroits qui te donnent le plus de pièces manquantes (donjon, métier, marchand), avec les boss concernés. Clic : ouvre le guide du donjon." }, en = { "Best gear, as a table per slot with gain, source and level; worn count, filters, and \"Next\": where the most missing pieces come from.", "" } },
    { s = "fix", fr = { "Meilleur équipement", "Plus de pièces de l'autre faction (réputations et marchands Alliance pour un Horde, et inversement), plus de pièces de raid ou de boss de monde (Quatre Cavaliers, Taerar...) dans le pré-BiS, plus de doublons." }, en = { "Best gear", "No pieces of the other faction, no raid or world boss pieces in the pre-BiS, no duplicates." } },
  } },
  { v = "1.0.0-beta.166", date = "2026-11-19", items = {
    { s = "add", fr = { "Meilleur équipement", "Une vraie fenêtre (/wlh bis, ou « Meilleur équipement » dans le hub) avec quatre onglets : « Pour ton niveau », « Pré-BiS 60 » (hors raid et hors PvP : donjons, quêtes, métiers, réputations), « BiS 60 (raids) » et « PvP 60 » (rangs d'honneur, réputations des champs de bataille). Pour chaque emplacement, les 3 meilleures pièces pour ta spé, avec leur provenance et le gain par rapport à ce que tu portes. Maj-clic pour mettre le lien dans la discussion. /wlh bis chat écrit toujours la liste dans la discussion." }, en = { "Best gear window", "For your level, pre-BiS 60, BiS 60 with raids, and PvP 60, per slot with source and gain." } },
    { s = "add", fr = { "Guide PvP : une fenêtre « Champs de bataille »", ". Une carte par champ de bataille : Goulet des Chanteguerres, Bassin d'Arathi, Vallée d'Alterac et Îles Darkspear." }, en = { "", "" } },
    { s = "add", fr = { "Réputation", "Ton rang avec la faction du champ de bataille (Warsong Outriders / Silverwing Sentinels, Defilers / League of Arathor, Frostwolf / Stormpike, Darkspear Raiders / Theramore Expeditionary Force) et les points qui restent jusqu'à Exalté." }, en = { "", "" } },
    { s = "add", fr = { "Parties restantes", "Le nombre de victoires ou de défaites qu'il faut encore. WL Helper mesure la réputation gagnée à chacune de tes parties (les 10 dernières par champ de bataille) et le dit dans le chat. Avant ta première partie, le Goulet et Arathi donnent un ordre de grandeur de Classic, pas encore confirmé sur Forever. Alterac et les Îles Darkspear attendent une partie mesurée." }, en = { "", "" } },
    { s = "add", fr = { "Maître de guerre", "Le plus proche de ton côté (Orgrimmar, Undercity, Thunder Bluff ; Hurlevent, Forgefer, Darnassus et Dalaran côté Alliance), avec un bouton « Y aller » pour le GPS. Positions tirées des données du client et recoupées avec Wowhead Forever. À vérifier en jeu : le maître d'Arathi de Thunder Bluff, que les données placent loin du Hunter Rise." }, en = { "", "" } },
    { s = "add", fr = { "Bonus de la semaine", "Lu dans le calendrier du jeu, pour aujourd'hui et les 7 prochains jours. Forever ne publie pas de rotation fixe, donc rien n'est deviné." }, en = { "", "" } },
    { s = "add", fr = { "", "Le set PvP (prix, ce qui te manque) est en bas de la fenêtre. /wlh pvp chat l'écrit toujours dans le chat." }, en = { "PvP guide", "A Battlegrounds window with each battleground's reputation, points to Exalted, the games left (measured on your own games), the nearest battlemaster with a GPS button, and the bonus battleground read from the game's calendar." } },
    { s = "fix", fr = { "GPS après une téléportation de mage", "Après une téléportation, un portail ou un écran de chargement, le trajet est recalculé depuis l'endroit où tu arrives. Avec Shortest Path, la destination lui est renvoyée. Avant, le guide pouvait encore t'envoyer prendre le zeppelin depuis Orgrimmar." }, en = { "GPS", "The trip is planned again after a teleport, a portal or a loading screen." } },
    { s = "fix", fr = { "Scarlet Diversions", "L'étape « brûler la tente et planter la bannière » manquait, donc le guide envoyait directement rendre la quête. Elle a maintenant sa flèche vers le camp écarlate, entre le champ de Felstone et les Larmes de Dalson, et une note pour la Flame in a Bottle." }, en = { "Scarlet Diversions", "The objective step and its spot are back before the turn-in." } },
  } },
  { v = "1.0.0-beta.165", date = "2026-11-19", items = {
    { s = "chg", fr = { "Choix de guide, cartes refaites", "L'image du donjon occupe toute la carte, comme dans le journal de Naowh. En bas, sur un fondu : le nom en plus grand, puis les niveaux (colorés selon ton niveau) et la zone, avec le compteur de quêtes à droite. Une fine barre de progression suit le bord du bas. La case pour combiner des donjons est passée en haut à gauche. Le nombre de quêtes en attente d'un prérequis est dans l'infobulle." }, en = { "Guide picker", "Picture-first cards with the name, level range, zone and quest count at the bottom." } },
    { s = "chg", fr = { "Plus facile à lire", "Fonds moins noirs, textes secondaires plus clairs, bords de cartes visibles. Ça touche toutes les fenêtres de l'addon." }, en = { "Easier to read", "Lighter backgrounds, brighter secondary text, visible card edges in every window." } },
    { s = "chg", fr = { "Profondeurs de Rochenoire", "3 quêtes de Kargath comptent maintenant comme quêtes du donjon (TUER À VUE : nains Sombrefer, TUER À VUE : officiers, Discordance des flammes). Leur travail se fait dans BRD, et Naowh les compte aussi." }, en = { "Blackrock Depths", "3 Kargath quests done inside now count as the dungeon's quests." } },
  } },
  { v = "1.0.0-beta.164", date = "2026-11-19", items = {
    { s = "add", fr = { "Guides de quêtes hors donjon", "Un nouvel onglet « Quêtes » dans le choix de guide. Chaque carte suit une chaîne de quêtes dans le monde, de la première quête à la récompense. Elle se combine avec des donjons dans une seule route." }, en = { "", "" } },
    { s = "add", fr = { "Sac 16 places : Sac en peau de démon", ". La longue chaîne du Héros déchu de la Horde (marais des Chagrins, Terres foudroyées, Azshara, Strangleronce). Les élites de la fin demandent un groupe." }, en = { "", "" } },
    { s = "add", fr = { "Sac 16 places : Red Bag", ". L'ancienne chaîne de Season of Discovery, ouverte à toutes les classes : le robot sur la plage de Tanaris, la traversée à la nage, Nami à Long-Guet, puis le sac dans les steppes Ardentes." }, en = { "", "" } },
    { s = "add", fr = { "Sac 18 places : Sacoche de la poste d'Hyjal", ". Trois quêtes de courrier entre le sommet du mont Hyjal et Long-Guet." }, en = { "", "" } },
    { s = "add", fr = { "Attracteur élémentaire", ". La quête Unstable Magic du Cercle terrestre (Horde, Mulgore ; Alliance, Alterac), avec les meilleurs coins pour les 10 granules d'après Wowhead. Sources : Wowhead WoW Forever (pages des quêtes, articles sur les sacs), positions de NaowhForever, noms français du client." }, en = { "Quest guides outside dungeons", "A new \"Quests\" tab in the guide picker, with the Demon Hide Sack and Red Bag (16 slots), the Hyjal Postal Satchel (18 slots) and the Elemental Attractor chains." } },
  } },
  { v = "1.0.0-beta.163", date = "2026-11-19", items = {
    { s = "add", fr = { "Vue moderne, un bouton pour fermer", "Une croix en haut à droite ferme le guide. Il reste fermé après un rechargement. Le bouton de la minicarte, /wlh ou un bouton du guide le rouvre." }, en = { "Modern view", "A close button; the guide stays closed until reopened." } },
    { s = "fix", fr = { "Moins de retours à la fenêtre classique", "" }, en = { "", "" } },
    { s = "fix", fr = { "", "Le bouton de la minicarte et /wlh guide ouvraient la fenêtre classique quand la vue moderne était déjà affichée. Ils ferment maintenant la vue moderne, et un second clic la rouvre." }, en = { "", "" } },
    { s = "fix", fr = { "", "Les raccourcis « étape suivante / précédente » font défiler la vue moderne." }, en = { "", "" } },
    { s = "fix", fr = { "", "Lancer un guide n'affiche plus la fenêtre classique un instant." }, en = { "The minimap button and /wlh guide close the modern view instead of opening the window; next/previous step keys browse the modern view; starting a guide no longer flashes the window.", "" } },
    { s = "fix", fr = { "Allers-retours courts dans un donjon", "Quand une quête se prend dehors, près de l'entrée, après une étape faite dans le donjon, et que ses objectifs sont de nouveau dans le donjon, la route fait l'aller-retour juste après cette étape et garde le reste du donjon pour après. Avant, il fallait refaire le donjon. Cela concerne par exemple Scholomance (Eva Sarkhoff, devant la porte) et les œufs de la Rookery au Pic Rochenoire supérieur (Tinkee Steamboil). Si le PNJ est loin, une capitale par exemple, la route ne change pas." }, en = { "Short in-and-out trips", "A quest taken just outside a dungeon after a step inside, with objectives back inside, is fetched right after that step (Scholomance's Eva Sarkhoff, Upper Blackrock Spire's eggs)." } },
  } },
  { v = "1.0.0-beta.162", date = "2026-11-19", items = {
    { s = "fix", fr = { "Uldaman (Horde), la chaîne du collier", "La route faisait tout le donjon avant d'envoyer à Kargath traduire le journal, puis demandait « Trouver les Gemmes et la Source d'énergie ». Or ses gemmes tombent dans le donjon (Grimlok, Archaedas, une urne, une cache) : il fallait le refaire en entier. Maintenant, juste après les Restes d'un paladin (au début du donjon), la route te fait ressortir à Kargath voir Jarkal, puis revenir faire tout le donjon avec la quête des gemmes. Une note sur ces étapes l'explique : l'instance reste comme tu l'as laissée si tu reviens dans la demi-heure environ." }, en = { "Uldaman (Horde) necklace chain", "Out to Kargath right after the Remains of a Paladin, back in for the rest, so the gems quest is done in the same run." } },
  } },
  { v = "1.0.0-beta.161", date = "2026-11-18", items = {
    { s = "fix", fr = { "Améliorations, icônes des sacs", "Un objet que le tooltip dit « Presque pareil » gardait la flèche verte et un « +43 % » sur son icône dans les sacs (Guardian Talisman face à Theka's Last Breath). Les icônes suivent maintenant le tooltip : ni flèche ni pourcentage pour un objet presque pareil." }, en = { "Bag icons follow the tooltip", "No arrow and no percent on an item that is \"about the same\"." } },
  } },
  { v = "1.0.0-beta.160", date = "2026-11-18", items = {
    { s = "fix", fr = { "Les boutons du guide ouvrent la vue moderne", "« Mettre à jour le guide » et « Retour au guide » (résumé des donjons, clés), la page d'accueil, le hub, les réglages et la proposition à l'entrée d'un donjon ouvraient la fenêtre classique au lieu de la vue moderne. Ils ouvrent maintenant la vue moderne quand c'est la vue par défaut. La fenêtre classique s'ouvre seulement par l'entrée « Fenêtre » du menu de la vue moderne (et pendant la visite guidée, qui la montre)." }, en = { "Guide buttons (update / back to the guide, home, hub, keys, settings, dungeon entry) open the modern view when it is the default; the window only from its menu.", "" } },
  } },
  { v = "1.0.0-beta.159", date = "2026-11-18", items = {
    { s = "chg", fr = { "Vue moderne, le nom de la quête en titre", "Sur une étape à objectif (« Ramasser : Magenta Fungus Cap 1/12 »), le grand titre répétait la barre d'objectif et le nom de la quête restait noyé dans une ligne grise. Le titre est maintenant le nom de la quête, en doré. La barre dit quoi faire et combien, et la ligne grise ne répète plus le nom de la quête." }, en = { "Modern view", "On an objective step the title is the quest's name; the bar says what to do and how many." } },
  } },
  { v = "1.0.0-beta.158", date = "2026-11-18", items = {
    { s = "chg", fr = { "Trouver un groupe, plus clair", "Sur une fenêtre assez large, les filtres ne sont plus cachés dans une fenêtre qui s'ouvre par-dessus. Ils restent visibles dans une colonne à droite de la liste, comme dans LFG Forever, avec des titres de section en couleur (classes, niveau, langues, style de jeu, places libres). L'icône filtre masque ou réaffiche cette colonne. Sur une fenêtre étroite, rien ne change." }, en = { "Find a group", "On a wide window the filters stay visible in a column right of the list; the filter icon hides or shows it." } },
  } },
  { v = "1.0.0-beta.157", date = "2026-11-18", items = {
    { s = "add", fr = { "Onglets WL Helper dans la fenêtre Recherche de groupe du jeu", "Sous les onglets de droite (et sous celui de LFG Forever), deux onglets WL Helper. Le logo ouvre « Trouver un groupe », l'enclume ouvre « Commandes d'artisanat ». Un clic ferme la fenêtre du jeu (hors combat) et ouvre la nôtre. Ces onglets ne touchent à rien dans la fenêtre du jeu." }, en = { "Two WL Helper tabs on the game's Group Finder (under LFG Forever's): Find a group and Crafting orders.", "" } },
  } },
  { v = "1.0.0-beta.156", date = "2026-11-18", items = {
    { s = "fix", fr = { "Vue moderne, guide terminé", "La vue disparaissait à la fin d'un guide et on ne pouvait plus choisir de guide. Elle affiche maintenant « Guide terminé ! » avec le lien « Choisir un guide » (et la flèche ‹ pour revoir la dernière étape). Sans aucun guide chargé : « Aucun guide en cours » avec le même lien." }, en = { "Modern view", "A finished guide (or none loaded) shows a card with \"Pick a guide\" instead of vanishing." } },
    { s = "fix", fr = { "Améliorations, bijoux", "Un bijou à +9 Endurance s'affichait « +125 % » face à Theka's Last Breath, parce que ce dernier ne vaut presque rien en stats (sa valeur est son effet « Utiliser : »). Face à un objet sans presque aucune stat, l'écart est donné en points (« Presque pareil », ou l'écart réel). La ligne « Remplace » nomme le bijou vraiment comparé, et une ligne rappelle que les effets « Utiliser : » ne sont pas comptés." }, en = { "Upgrades", "No huge percent next to an item with almost no stats; \"Replaces\" names the trinket really compared; a note that \"Use:\" effects are not counted." } },
    { s = "fix", fr = { "Régénération de mana", "Pour les lanceurs de sorts (mage, démoniste, prêtre ombre...), 1 mana toutes les 5 s valait moins que 1 Intelligence, alors qu'elle rend plus de mana sur un combat. Elle vaut maintenant environ 1,6 fois le mana de l'Intelligence." }, en = { "Mana per 5 s for casters is worth about 1.6 times Intellect's mana (it was below Intellect).", "" } },
  } },
  { v = "1.0.0-beta.155", date = "2026-11-18", items = {
    { s = "fix", fr = { "Le GPS suit la vue moderne", "La fenêtre classique fermée, la flèche GPS suivait encore l'étape où cette fenêtre était restée (par exemple une étape du donjon), au lieu de l'étape affichée dans la vue moderne. Elle suit maintenant la vue moderne, y compris quand on parcourt les étapes avec ‹ ›, avec la liste ou en cliquant une action." }, en = { "The GPS arrow follows the modern view's step (and its browsing), not a step the closed window was left on.", "" } },
    { s = "fix", fr = { "Vue moderne, un texte plus propre", "Le lieu n'est plus écrit deux fois (seule la ligne avec la distance reste), les notes sans titre ont maintenant le titre « À savoir », et la ligne « Oathstone... » en trop sur « L'Essence d'Eranikus » a disparu." }, en = { "Modern view", "The place said once (with the distance), untitled notes under \"Good to know\", the stray Oathstone line gone." } },
  } },
}
